def analyze_external_inventory(events: List[Any]) -> Dict[str, Any]:
    """Analyzes attribute fields, failure areas, categories, and geometries of external events."""
    categories: Dict[str, int] = {}
    areas: List[float] = []
    missing_dates = 0
    valid_coords = 0

    for ev in events:
        props = ev.properties or {}
        cat = props.get("category") or props.get("category_1") or ev.landslide_type or "Unspecified"
        categories[cat] = categories.get(cat, 0) + 1

        area_val = props.get("area") or props.get("Area_1")
        if area_val is not None:
            try:
                areas.append(float(area_val))
            except (ValueError, TypeError):
                pass

        d = ev.event_date or ""
        if not d.strip() or d.strip() == "18991230":
            missing_dates += 1

        if ev.latitude and ev.longitude:
            valid_coords += 1

    return {
        "total_records": len(events),
        "valid_geometries": valid_coords,
        "invalid_geometries": len(events) - valid_coords,
        "categories": categories,
        "area_count": len(areas),
        "area_min_m2": round(float(min(areas)), 2) if areas else 0.0,
        "area_max_m2": round(float(max(areas)), 2) if areas else 0.0,
        "area_mean_m2": round(float(np.mean(areas)), 2) if areas else 0.0,
        "area_median_m2": round(float(np.median(areas)), 2) if areas else 0.0,
        "missing_dates_count": missing_dates,
    }


