def run_external_validation(
    intake_dir: Path = DEFAULT_INTAKE_DIR,
    input_file: Optional[Path | str] = None,
    exclusion_buffer_m: float = 500.0,
    negative_ratio: float = 1.0,
    random_seed: int = 42,
    report_out_path: Path = DEFAULT_REPORT_OUT,
) -> Dict[str, Any]:
    """
    Executes end-to-end frozen M6 external validation pipeline.
    """
    intake_dir.mkdir(parents=True, exist_ok=True)
    report_out_path.parent.mkdir(parents=True, exist_ok=True)

    contract = FrozenModelContract()
    model_sha = contract.verify_integrity(REPO_ROOT)

    loader = ExternalLandslideLoader()
    loaded_inventory: Optional[LoadedExternalInventory] = None

    if input_file is not None:
        target_file = Path(input_file)
        if not target_file.exists():
            raise FileNotFoundError(f"Specified external file not found: {target_file}")
        if target_file.suffix.lower() in (".geojson", ".json"):
            loaded_inventory = loader.load_geojson(target_file)
        elif target_file.suffix.lower() == ".csv":
            loaded_inventory = loader.load_csv(target_file)
        elif target_file.suffix.lower() == ".shp":
            loaded_inventory = loader.load_shapefile(target_file)
        else:
            raise ValueError(f"Unsupported file format: {target_file.suffix}")
    else:
        loaded_inventory = loader.load_from_directory(intake_dir)

    # 1. Handle Missing External Dataset (Empty folder)
    if loaded_inventory is None:
        missing_msg = f"No external historical landslide inventory file found in {intake_dir}."
        report_md = generate_markdown_report(
            eval_result=None,
            loaded_inv=None,
            independence_audit=None,
            sampling_report=None,
            provenance=None,
            state=ExternalValidationState.NOT_POSSIBLE,
            missing_reason=missing_msg,
            model_sha256=model_sha,
        )
        with open(report_out_path, "w", encoding="utf-8") as f:
            f.write(report_md)

        return {
            "validation_status": ExternalValidationState.NOT_POSSIBLE.value,
            "status": "VALIDATION NOT POSSIBLE WITH CURRENT EXTERNAL DATA",
            "message": missing_msg,
            "intake_directory": str(intake_dir),
            "instructions": (
                "Place an independent historical landslide dataset (.geojson, .shp, or .csv) "
                f"into {intake_dir} and rerun."
            ),
            "report_path": str(report_out_path),
        }

    # 2. Case: External Dataset Present, but 0 events inside Upper Beas AOI
    if len(loaded_inventory.events_inside_aoi) == 0:
        auditor = IndependenceAuditor()
        # Audit all events against Upper Beas training points
        _, indep_audit = auditor.audit_independence(
            loaded_inventory.all_events or [],
            external_dataset_name=loaded_inventory.dataset_record.dataset_name,
        )

        inv_analysis = analyze_external_inventory(loaded_inventory.all_events)

        # Export GIS Deliverables
        exporter = ExternalValidationMapExporter()
        exported_maps = exporter.export_unvalidated_inventory(
            loaded_inventory.all_events,
            loaded_inventory.dataset_record,
        )

        report_md = generate_markdown_report(
            eval_result=None,
            loaded_inv=loaded_inventory,
            independence_audit=indep_audit,
            sampling_report=None,
            provenance=None,
            state=ExternalValidationState.EXTERNAL_VALIDATION_PENDING,
            model_sha256=model_sha,
            inventory_analysis=inv_analysis,
        )
        with open(report_out_path, "w", encoding="utf-8") as f:
            f.write(report_md)

        return {
            "validation_status": ExternalValidationState.EXTERNAL_VALIDATION_PENDING.value,
            "status": "EXTERNAL VALIDATION PENDING — ZERO OBSERVATIONS INSIDE UPPER BEAS AOI",
            "dataset_name": loaded_inventory.dataset_record.dataset_name,
            "provider": loaded_inventory.dataset_record.provider,
            "source_doi": "10.5281/zenodo.10492992",
            "file_sha256": loaded_inventory.dataset_record.sha256_hash,
            "raw_event_count": loaded_inventory.total_raw_events,
            "events_inside_aoi": len(loaded_inventory.events_inside_aoi),
            "events_outside_aoi": loaded_inventory.events_outside_aoi_count,
            "percentage_inside_aoi": loaded_inventory.percentage_inside_aoi,
            "positive_validation_samples": 0,
            "negative_samples": 0,
            "spatial_exclusion_distance_m": exclusion_buffer_m,
            "training_overlap_result": "SPATIALLY DISJOINT (100% independent, >55km)",
            "temporal_independence_result": "UNVERIFIABLE (training data lacks event timestamps)",
            "model_id": FrozenModelContract.model_id,
            "model_version": FrozenModelContract.model_version,
            "model_sha256": model_sha,
            "metrics": {
                "roc_auc": "NOT COMPUTABLE — INSUFFICIENT EXTERNAL DATA",
                "pr_auc": "NOT COMPUTABLE — INSUFFICIENT EXTERNAL DATA",
                "precision": "NOT COMPUTABLE — INSUFFICIENT EXTERNAL DATA",
                "recall": "NOT COMPUTABLE — INSUFFICIENT EXTERNAL DATA",
                "f1_score": "NOT COMPUTABLE — INSUFFICIENT EXTERNAL DATA",
                "specificity": "NOT COMPUTABLE — INSUFFICIENT EXTERNAL DATA",
                "brier_score": "NOT COMPUTABLE — INSUFFICIENT EXTERNAL DATA",
                "expected_calibration_error": "NOT COMPUTABLE — INSUFFICIENT EXTERNAL DATA",
            },
            "spatial_capture_rates": {
                "top_10_percent": "NOT COMPUTABLE — INSUFFICIENT EXTERNAL DATA",
                "top_20_percent": "NOT COMPUTABLE — INSUFFICIENT EXTERNAL DATA",
                "top_30_percent": "NOT COMPUTABLE — INSUFFICIENT EXTERNAL DATA",
                "hit_rate": "NOT COMPUTABLE — INSUFFICIENT EXTERNAL DATA",
            },
            "baseline_comparison": {
                "slope_only_roc_auc": "NOT COMPUTABLE — INSUFFICIENT EXTERNAL DATA",
                "random_roc_auc": "NOT COMPUTABLE — INSUFFICIENT EXTERNAL DATA",
            },
            "gis_products": {k: str(v) for k, v in exported_maps.items()},
            "report_path": str(report_out_path),
            "inventory_analysis": inv_analysis,
        }

    # 3. Case: Events inside AOI > 0
    auditor = IndependenceAuditor()
    clean_events, indep_audit = auditor.audit_independence(
        loaded_inventory.events_inside_aoi,
        external_dataset_name=loaded_inventory.dataset_record.dataset_name,
    )

    if len(clean_events) == 0:
        missing_msg = "All external events were co-located with M6 training points; zero independent events remain."
        report_md = generate_markdown_report(
            eval_result=None,
            loaded_inv=loaded_inventory,
            independence_audit=indep_audit,
            sampling_report=None,
            provenance=None,
            state=ExternalValidationState.NOT_POSSIBLE,
            missing_reason=missing_msg,
            model_sha256=model_sha,
        )
        with open(report_out_path, "w", encoding="utf-8") as f:
            f.write(report_md)

        return {
            "validation_status": ExternalValidationState.NOT_POSSIBLE.value,
            "status": "VALIDATION NOT POSSIBLE WITH CURRENT EXTERNAL DATA",
            "message": missing_msg,
            "report_path": str(report_out_path),
        }

    # 4. Spatial Sampling with Exclusion Buffer
    sampler = SpatialLeakageController(
        exclusion_buffer_m=exclusion_buffer_m,
        negative_ratio=negative_ratio,
        random_seed=random_seed,
    )
    validation_points, sampling_report = sampler.generate_evaluation_set(clean_events)

    # 5. Feature Extraction Adhering to Exact M6 Contract
    extractor = M6FeatureExtractor()
    coords = [(pt.latitude, pt.longitude) for pt in validation_points]
    features_df, feat_prov = extractor.extract_features_for_points(coords)

    # 6. Frozen M6 Inference and Metrics
    evaluator = FrozenM6Evaluator()
    eval_result = evaluator.evaluate(
        validation_points=validation_points,
        features_df=features_df,
        dataset_id=loaded_inventory.dataset_record.dataset_id,
        random_seed=random_seed,
    )

    # 7. Export GIS Map Products
    exporter = ExternalValidationMapExporter()
    exported_maps = exporter.export_all(eval_result)

    # 8. Final Status Determination
    final_state = (
        ExternalValidationState.EXTERNALLY_VALIDATED
        if eval_result.roc_auc >= 0.70 and eval_result.positive_events_count >= 10
        else ExternalValidationState.PARTIALLY_VALIDATED
    )

    # 9. Generate and Write Validation Report
    report_md = generate_markdown_report(
        eval_result=eval_result,
        loaded_inv=loaded_inventory,
        independence_audit=indep_audit,
        sampling_report=sampling_report,
        provenance=feat_prov,
        state=final_state,
        model_sha256=model_sha,
    )
    with open(report_out_path, "w", encoding="utf-8") as f:
        f.write(report_md)

    return {
        "validation_status": final_state.value,
        "dataset_name": loaded_inventory.dataset_record.dataset_name,
        "provider": loaded_inventory.dataset_record.provider,
        "source_doi": "10.5281/zenodo.10492992",
        "file_sha256": loaded_inventory.dataset_record.sha256_hash,
        "raw_event_count": loaded_inventory.total_raw_events,
        "events_inside_aoi": len(loaded_inventory.events_inside_aoi),
        "events_outside_aoi": loaded_inventory.events_outside_aoi_count,
        "percentage_inside_aoi": loaded_inventory.percentage_inside_aoi,
        "independent_events_evaluated": eval_result.positive_events_count,
        "negative_samples_count": eval_result.negative_samples_count,
        "exclusion_buffer_m": exclusion_buffer_m,
        "model_id": FrozenModelContract.model_id,
        "model_version": FrozenModelContract.model_version,
        "model_sha256": model_sha,
        "metrics": {
            "accuracy": eval_result.accuracy,
            "precision": eval_result.precision,
            "recall": eval_result.recall,
            "specificity": eval_result.specificity,
            "f1_score": eval_result.f1_score,
            "roc_auc": eval_result.roc_auc,
            "pr_auc": eval_result.pr_auc,
            "brier_score": eval_result.brier_score,
            "expected_calibration_error": eval_result.expected_calibration_error,
        },
        "spatial_capture_rates": {
            "top_10_percent": eval_result.spatial_capture_rates.top_10_percent_capture_rate,
            "top_20_percent": eval_result.spatial_capture_rates.top_20_percent_capture_rate,
            "top_30_percent": eval_result.spatial_capture_rates.top_30_percent_capture_rate,
            "hit_rate": eval_result.spatial_capture_rates.spatial_hit_rate,
        },
        "baseline_comparison": {
            "m6_roc_auc": eval_result.baseline_m6.roc_auc,
            "slope_only_roc_auc": eval_result.baseline_slope_only.roc_auc,
            "random_roc_auc": eval_result.baseline_random.roc_auc,
        },
        "gis_products": {k: str(v) for k, v in exported_maps.items()},
        "report_path": str(report_out_path),
    }


def main():
    parser = argparse.ArgumentParser(description="M6 Landslide Susceptibility External Validation Runner")
    parser.add_argument("--intake-dir", type=Path, default=DEFAULT_INTAKE_DIR, help="Directory containing external datasets")
    parser.add_argument("--input-file", type=Path, default=None, help="Specific external file path")
    parser.add_argument("--exclusion-buffer-m", type=float, default=500.0, help="Negative sampling exclusion buffer (meters)")
    parser.add_argument("--negative-ratio", type=float, default=1.0, help="Negative to positive sample ratio")
    parser.add_argument("--random-seed", type=int, default=42, help="Fixed random seed for deterministic sampling")
    parser.add_argument("--report-out", type=Path, default=DEFAULT_REPORT_OUT, help="Path for generated Markdown report")

    args = parser.parse_args()

    print("=" * 72)
    print("FLOODY SHIELD — MODEL M6 EXTERNAL SCIENTIFIC VALIDATION PIPELINE")
    print("=" * 72)
    print(f"Intake Directory   : {args.intake_dir}")
    print(f"Exclusion Buffer   : {args.exclusion_buffer_m} meters")
    print(f"Random Seed        : {args.random_seed}")
    print(f"Report Output Path : {args.report_out}")
    print("-" * 72)

    res = run_external_validation(
        intake_dir=args.intake_dir,
        input_file=args.input_file,
        exclusion_buffer_m=args.exclusion_buffer_m,
        negative_ratio=args.negative_ratio,
        random_seed=args.random_seed,
        report_out_path=args.report_out,
    )

    def _fmt(val: Any) -> str:
        if isinstance(val, (float, int)):
            return f"{val:.4f}"
        return str(val)

    print()
    print(f"STATUS: {res['validation_status']}")
    if "dataset_name" in res:
        print(f"DATASET            : {res['dataset_name']}")
        print(f"SHA-256            : {res.get('file_sha256', '')[:16]}...")
        print(f"RAW RECORDS        : {res.get('raw_event_count')}")
        print(f"IN-AOI EVENTS      : {res.get('events_inside_aoi')} ({res.get('percentage_inside_aoi', 0.0)}%)")
        print(f"OUT-AOI EVENTS     : {res.get('events_outside_aoi')}")
    if "metrics" in res:
        m = res["metrics"]
        print("METRICS:")
        print(f"  ROC-AUC          : {_fmt(m.get('roc_auc'))}")
        print(f"  PR-AUC           : {_fmt(m.get('pr_auc'))}")
        print(f"  F1-Score         : {_fmt(m.get('f1_score'))}")
        print(f"  Brier Score      : {_fmt(m.get('brier_score'))}")
        print(f"  ECE (Calibration): {_fmt(m.get('expected_calibration_error'))}")
        if "spatial_capture_rates" in res:
            sc = res["spatial_capture_rates"]
            val20 = sc.get('top_20_percent')
            print(f"  Top 20% Capture  : {_fmt(val20 if not isinstance(val20, (float, int)) else val20*100.0)}")
    else:
        print(f"REASON             : {res.get('message')}")
        print(f"INSTRUCTIONS       : {res.get('instructions')}")

    print(f"REPORT             : {res.get('report_path')}")
    print("=" * 72)


if __name__ == "__main__":
    main()
